// upsampler.js
// Node.js 18+
// Usage:
//   node upsampler.js input.jpg
//   node upsampler.js input.png output-folder

const fs = require("fs");
const path = require("path");
const crypto = require("crypto");

const BASE = "https://upsampler-media-upscaler.hf.space";
const ORIGIN = "https://upsampler.com";

const MODEL = "4xNomosWebPhotoRealPLKSR";
const FN_INDEX = 1;

function sessionHash() {
  // Format pendek seperti session_hash Gradio.
    return crypto.randomBytes(8).toString("hex").slice(0, 11);
    }

    function safeFilename(name, fallback = "image.webp") {
      const clean = path.basename(name || fallback).replace(/[^\w.-]/g, "_");
        return clean || fallback;
        }

        // 1. Upload gambar ke Gradio
        async function uploadImage(filePath) {
          if (!fs.existsSync(filePath)) {
              throw new Error(`File tidak ditemukan: ${filePath}`);
                }

                  const buffer = fs.readFileSync(filePath);
                    const blob = new Blob([buffer]);

                      const form = new FormData();
                        form.append("files", blob, path.basename(filePath));

                          console.log("[1/4] Upload...");

                            const res = await fetch(`${BASE}/gradio_api/upload`, {
                                method: "POST",
                                    headers: {
                                          Origin: ORIGIN,
                                                Referer: `${ORIGIN}/`,
                                                    },
                                                        body: form,
                                                          });

                                                            if (!res.ok) {
                                                                throw new Error(
                                                                      `Upload gagal (${res.status}): ${await res.text()}`
                                                                          );
                                                                            }

                                                                              const data = await res.json();

                                                                                if (!Array.isArray(data) || !data[0]) {
                                                                                    throw new Error(`Response upload tidak dikenali: ${JSON.stringify(data)}`);
                                                                                      }

                                                                                        console.log("Uploaded:", data[0]);

                                                                                          return data[0];
                                                                                          }

                                                                                          // 2. Masukkan job ke queue
                                                                                          async function joinQueue(uploadedPath, session) {
                                                                                            console.log("[2/4] Submit upscale job...");

                                                                                              const payload = {
                                                                                                  data: [
                                                                                                        {
                                                                                                                path: uploadedPath,
                                                                                                                        meta: {
                                                                                                                                  _type: "gradio.FileData",
                                                                                                                                          },
                                                                                                                                                },
                                                                                                                                                      MODEL,
                                                                                                                                                            false,
                                                                                                                                                                ],
                                                                                                                                                                    event_data: null,
                                                                                                                                                                        fn_index: FN_INDEX,
                                                                                                                                                                            trigger_id: null,
                                                                                                                                                                                session_hash: session,
                                                                                                                                                                                  };

                                                                                                                                                                                    const res = await fetch(`${BASE}/gradio_api/queue/join`, {
                                                                                                                                                                                        method: "POST",
                                                                                                                                                                                            headers: {
                                                                                                                                                                                                  "Content-Type": "application/json",
                                                                                                                                                                                                        "x-gradio-user": "api",
                                                                                                                                                                                                              Origin: ORIGIN,
                                                                                                                                                                                                                    Referer: `${ORIGIN}/`,
                                                                                                                                                                                                                        },
                                                                                                                                                                                                                            body: JSON.stringify(payload),
                                                                                                                                                                                                                              });

                                                                                                                                                                                                                                if (!res.ok) {
                                                                                                                                                                                                                                    throw new Error(
                                                                                                                                                                                                                                          `Queue join gagal (${res.status}): ${await res.text()}`
                                                                                                                                                                                                                                              );
                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                  const data = await res.json();

                                                                                                                                                                                                                                                    console.log("Queue:", data);

                                                                                                                                                                                                                                                      return data;
                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                      // 3. Dengarkan SSE sampai process_completed
                                                                                                                                                                                                                                                      async function waitForResult(session) {
                                                                                                                                                                                                                                                        console.log("[3/4] Menunggu proses...");

                                                                                                                                                                                                                                                          const res = await fetch(
                                                                                                                                                                                                                                                              `${BASE}/gradio_api/queue/data?session_hash=${encodeURIComponent(session)}`,
                                                                                                                                                                                                                                                                  {
                                                                                                                                                                                                                                                                        headers: {
                                                                                                                                                                                                                                                                                Accept: "text/event-stream",
                                                                                                                                                                                                                                                                                        "Content-Type": "application/json",
                                                                                                                                                                                                                                                                                                Origin: ORIGIN,
                                                                                                                                                                                                                                                                                                        Referer: `${ORIGIN}/`,
                                                                                                                                                                                                                                                                                                              },
                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                    );

                                                                                                                                                                                                                                                                                                                      if (!res.ok) {
                                                                                                                                                                                                                                                                                                                          throw new Error(
                                                                                                                                                                                                                                                                                                                                `Queue stream gagal (${res.status}): ${await res.text()}`
                                                                                                                                                                                                                                                                                                                                    );
                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                        if (!res.body) {
                                                                                                                                                                                                                                                                                                                                            throw new Error("SSE stream tidak tersedia.");
                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                const reader = res.body.getReader();
                                                                                                                                                                                                                                                                                                                                                  const decoder = new TextDecoder();

                                                                                                                                                                                                                                                                                                                                                    let buffer = "";

                                                                                                                                                                                                                                                                                                                                                      while (true) {
                                                                                                                                                                                                                                                                                                                                                          const { value, done } = await reader.read();

                                                                                                                                                                                                                                                                                                                                                              if (done) break;

                                                                                                                                                                                                                                                                                                                                                                  buffer += decoder.decode(value, { stream: true });

                                                                                                                                                                                                                                                                                                                                                                      // SSE event dipisahkan blank line.
                                                                                                                                                                                                                                                                                                                                                                          const events = buffer.split(/\r?\n\r?\n/);
                                                                                                                                                                                                                                                                                                                                                                              buffer = events.pop() || "";

                                                                                                                                                                                                                                                                                                                                                                                  for (const event of events) {
                                                                                                                                                                                                                                                                                                                                                                                        const dataLines = event
                                                                                                                                                                                                                                                                                                                                                                                                .split(/\r?\n/)
                                                                                                                                                                                                                                                                                                                                                                                                        .filter((line) => line.startsWith("data:"))
                                                                                                                                                                                                                                                                                                                                                                                                                .map((line) => line.slice(5).trim());

                                                                                                                                                                                                                                                                                                                                                                                                                      if (!dataLines.length) continue;

                                                                                                                                                                                                                                                                                                                                                                                                                            let msg;

                                                                                                                                                                                                                                                                                                                                                                                                                                  try {
                                                                                                                                                                                                                                                                                                                                                                                                                                          msg = JSON.parse(dataLines.join("\n"));
                                                                                                                                                                                                                                                                                                                                                                                                                                                } catch {
                                                                                                                                                                                                                                                                                                                                                                                                                                                        continue;
                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                    switch (msg.msg) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            case "estimation":
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      console.log(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  `Queue rank: ${msg.rank ?? "?"} | ETA: ${
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                msg.rank_eta?.toFixed?.(1) ?? "?"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }s`
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                break;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        case "process_starts":
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  console.log("Upscaling dimulai...");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            break;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    case "process_completed": {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (msg.success === false) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          throw new Error(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        `Upscale gagal: ${JSON.stringify(msg.output)}`
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return msg.output;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        case "close_stream":
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  throw new Error("Stream ditutup sebelum hasil diterima.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                throw new Error("SSE berakhir tanpa process_completed.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Normalisasi output Gradio.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Capture lu menunjukkan output.data = [[FileData, FileData]]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                function extractFiles(output) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const found = [];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function walk(value) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (!value) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (Array.isArray(value)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  for (const item of value) walk(item);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (typeof value === "object") {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              value.url &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      (value.meta?._type === "gradio.FileData" || value.path)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    found.push(value);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        for (const child of Object.values(value)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                walk(child);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              walk(output?.data);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return found;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // 4. Download hasil
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                async function downloadResult(file, outputPath) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const url =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      file.url ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          `${BASE}/gradio_api/file=${file.path}`;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const res = await fetch(url, {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                headers: {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      Origin: ORIGIN,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Referer: `${ORIGIN}/`,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (!res.ok) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        throw new Error(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              `Download gagal (${res.status}): ${await res.text()}`
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const buffer = Buffer.from(await res.arrayBuffer());

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        fs.writeFileSync(outputPath, buffer);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          return buffer.length;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          async function upscale(input, outputDir = "./output") {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const session = sessionHash();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              console.log("Input :", input);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                console.log("Model :", MODEL);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  console.log("Session:", session);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    console.log();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const uploadedPath = await uploadImage(input);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        await joinQueue(uploadedPath, session);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const output = await waitForResult(session);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const files = extractFiles(output);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (!files.length) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  throw new Error(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        `Tidak menemukan FileData pada output:\n${JSON.stringify(output, null, 2)}`
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                fs.mkdirSync(outputDir, { recursive: true });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  console.log(`[4/4] Download ${files.length} hasil...`);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const downloaded = [];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      for (let i = 0; i < files.length; i++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const file = files[i];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              let name = safeFilename(file.orig_name);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  // Karena capture lu menghasilkan dua image.webp,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // cegah file kedua menimpa yang pertama.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (files.length > 1) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const ext = path.extname(name) || ".webp";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const stem = path.basename(name, ext);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            name = `${stem}-${i + 1}${ext}`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const outputPath = path.join(outputDir, name);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const bytes = await downloadResult(file, outputPath);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            downloaded.push(outputPath);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                console.log(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      `✓ ${outputPath} (${(bytes / 1024 / 1024).toFixed(2)} MB)`
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return downloaded;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              // CLI
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              (async () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const input = process.argv[2];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const outputDir = process.argv[3] || "./output";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (!input) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  console.log("Usage:");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        console.log("  node upsampler.js <image> [output-folder]");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              console.log();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    console.log("Example:");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          console.log("  node upsampler.js foto.jpg");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                console.log("  node upsampler.js foto.png ./hasil");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      process.exit(1);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const results = await upscale(input, outputDir);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  console.log("\nSelesai.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      console.log(results.join("\n"));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        } catch (err) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            console.error("\nERROR:", err.message);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                process.exit(1);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  })();